import{_ as i,C as a,c as e,o as t,a0 as o,b as r,w as l,a as n,G as s,a1 as u}from"./chunks/framework.DKRgXLPU.js";const p=JSON.parse('{"title":"Guida alla sessione: Introduzione al gioco mentale (2-3 ore)","description":"","frontmatter":{},"headers":[],"relativePath":"it/mental-journey/session-guide.md","filePath":"it/mental-journey/session-guide.md"}');const c=i({name:"it/mental-journey/session-guide.md"},[["render",function(i,p,c,d,m,g){const h=a("Mermaid");return t(),e("div",null,[p[1]||(p[1]=o('<h1 id="guida-alla-sessione-introduzione-al-gioco-mentale-2-3-ore" tabindex="-1">Guida alla sessione: Introduzione al gioco mentale (2-3 ore) <a class="header-anchor" href="#guida-alla-sessione-introduzione-al-gioco-mentale-2-3-ore" aria-label="Permalink to &quot;Guida alla sessione: Introduzione al gioco mentale (2-3 ore)&quot;">​</a></h1><h2 id="panoramica" tabindex="-1">Panoramica <a class="header-anchor" href="#panoramica" aria-label="Permalink to &quot;Panoramica&quot;">​</a></h2><p>Questa guida ti aiuterà a condurre una sessione introduttiva di 2-3 ore sull&#39;allenamento mentale per giocatori di pétanque. Perfetta per allenatori, dirigenti di club o giocatori esperti che desiderano introdurre l&#39;allenamento mentale alla propria squadra.</p><div class="tip custom-block"><p class="custom-block-title">Due sezioni in questa guida</p><ul><li><strong><a href="#for-participants">Per i partecipanti</a></strong> - Cosa impareranno i giocatori</li><li><strong><a href="#for-facilitators">Per i facilitatori</a></strong> - Come condurre la sessione</li></ul></div><h2 id="accesso-rapido" tabindex="-1">Accesso rapido <a class="header-anchor" href="#accesso-rapido" aria-label="Permalink to &quot;Accesso rapido&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Sezione</th><th>Scopo</th><th>Accesso</th></tr></thead><tbody><tr><td><strong>Per i partecipanti</strong></td><td>Cosa aspettarsi dalla sessione</td><td><a href="#for-participants">Visualizza sezione</a></td></tr><tr><td><strong>Per i facilitatori</strong></td><td>Piano completo della sessione e tempistica</td><td><a href="#for-facilitators">Visualizza sezione</a></td></tr><tr><td><strong>Materiali della sessione</strong></td><td>Guide, diapositive e fogli di lavoro</td><td><a href="/it/mental-journey/materials">Visualizza materiali</a></td></tr><tr><td><strong>Lista di controllo per la preparazione</strong></td><td>Cosa preparare prima della sessione</td><td><a href="#preparazione-1-settimana-prima">Visualizza la lista di controllo</a></td></tr></tbody></table><hr><h2 id="per-i-partecipanti" tabindex="-1">Per i partecipanti <a class="header-anchor" href="#per-i-partecipanti" aria-label="Permalink to &quot;Per i partecipanti&quot;">​</a></h2><h3 id="cosa-aspettarsi" tabindex="-1">Cosa aspettarsi <a class="header-anchor" href="#cosa-aspettarsi" aria-label="Permalink to &quot;Cosa aspettarsi&quot;">​</a></h3><p>Questa sessione introduce il gioco mentale della pétanque attraverso discussioni, esercizi e tecniche pratiche che puoi utilizzare immediatamente.</p><p><strong>Imparerai:</strong></p><ul><li>Perché l&#39;allenamento mentale è importante per le prestazioni</li><li>La differenza tra &quot;modalità tecnica&quot; e &quot;modalità di flusso&quot;</li><li>Come riconoscere e gestire il tuo critico interiore</li><li>Semplici tecniche per la gestione della pressione</li><li>Una routine di base prima del tiro</li></ul><p><strong>Cosa ti servirà:</strong></p><ul><li>Mente aperta e disponibilità a condividere</li><li>Quaderno e penna</li><li>Le tue esperienze personali da discutere</li><li>2-3 ore di tempo concentrato</li></ul><h3 id="struttura-della-sessione" tabindex="-1">Struttura della sessione <a class="header-anchor" href="#struttura-della-sessione" aria-label="Permalink to &quot;Struttura della sessione&quot;">​</a></h3>',15)),(t(),r(u,null,{default:l(()=>[s(h,{id:"mermaid-155",class:"mermaid",graph:"graph%20LR%0A%20%20%20%20A%5BIntroduzione%20%3Cbr%2F%3E%2020%20minuti%5D%20--%3E%20B%5BLa%20zona%20%3Cbr%2F%3E%2040%20minuti%5D%0A%20%20%20%20B%20--%3E%20C%5BRottura%20%3Cbr%2F%3E%2010%20minuti%5D%0A%20%20%20%20C%20--%3E%20D%5BCritico%20interiore%20%3Cbr%2F%3E%2040%20minuti%5D%0A%20%20%20%20D%20--%3E%20E%5BStrumenti%20pratici%20%3Cbr%2F%3E%2040%20minuti%5D%0A%20%20%20%20E%20--%3E%20F%5BIntegrazione%20%3Cbr%2F%3E%2020%20minuti%5D%0A%20%20%20%20%0A%20%20%20%20style%20A%20fill%3A%23e3f2fd%0A%20%20%20%20style%20B%20fill%3A%23fff4e1%0A%20%20%20%20style%20C%20fill%3A%23f3e5f5%0A%20%20%20%20style%20D%20fill%3A%23ffe4e1%0A%20%20%20%20style%20E%20fill%3A%23e8f5e9%0A%20%20%20%20style%20F%20fill%3A%23c8e6c9%0A"})]),fallback:l(()=>[...p[0]||(p[0]=[n(" Loading... ",-1)])]),_:1})),p[2]||(p[2]=o('<h3 id="concetti-chiave-che-esplorerai" tabindex="-1">Concetti chiave che esplorerai <a class="header-anchor" href="#concetti-chiave-che-esplorerai" aria-label="Permalink to &quot;Concetti chiave che esplorerai&quot;">​</a></h3><h4 id="_1-la-zona-stato-di-flusso" tabindex="-1">1. La zona (stato di flusso) <a class="header-anchor" href="#_1-la-zona-stato-di-flusso" aria-label="Permalink to &quot;1. La zona (stato di flusso)&quot;">​</a></h4><ul><li>Cosa si prova quando tutto funziona</li><li>Perché pensare alla tecnica compromette la prestazione</li><li>Il &quot;passaggio&quot; dalla pianificazione all&#39;esecuzione</li></ul><h4 id="_2-il-critico-interiore" tabindex="-1">2. Il critico interiore <a class="header-anchor" href="#_2-il-critico-interiore" aria-label="Permalink to &quot;2. Il critico interiore&quot;">​</a></h4><ul><li>Come il dialogo interiore negativo influisce sulle prestazioni</li><li>La differenza tra Critico Interiore e Coach Interiore</li><li>Osservazione neutrale vs giudizio severo</li></ul><h4 id="_3-risposta-alla-pressione" tabindex="-1">3. Risposta alla pressione <a class="header-anchor" href="#_3-risposta-alla-pressione" aria-label="Permalink to &quot;3. Risposta alla pressione&quot;">​</a></h4><ul><li>Perché giochi in modo diverso in competizione</li><li>Segni fisici di pressione</li><li>Tecniche di ripristino rapido</li></ul><h4 id="_4-strumenti-pratici" tabindex="-1">4. Strumenti pratici <a class="header-anchor" href="#_4-strumenti-pratici" aria-label="Permalink to &quot;4. Strumenti pratici&quot;">​</a></h4><ul><li>Reset a 3 respiri</li><li>Semplice routine pre-tiro</li><li>Protocollo di recupero degli errori</li></ul><h3 id="cosa-portare" tabindex="-1">Cosa portare <a class="header-anchor" href="#cosa-portare" aria-label="Permalink to &quot;Cosa portare&quot;">​</a></h3><p><strong>Necessario:</strong></p><ul><li>Te stesso e le tue esperienze</li><li>Disponibilità a partecipare</li></ul><p><strong>Opzionale:</strong></p><ul><li>Esempi di sfide mentali che affronti</li><li>Domande su situazioni specifiche</li><li>Quaderno per appunti personali</li></ul><h3 id="dopo-la-sessione" tabindex="-1">Dopo la sessione <a class="header-anchor" href="#dopo-la-sessione" aria-label="Permalink to &quot;Dopo la sessione&quot;">​</a></h3><p>Riceverai:</p><ul><li>Riepilogo dei concetti chiave</li><li>Esercizi pratici per la settimana</li><li>Link ai moduli didattici dettagliati</li><li>Modello di obiettivo per lo sviluppo del gioco mentale</li></ul><hr><h2 id="per-i-facilitatori" tabindex="-1">Per i facilitatori <a class="header-anchor" href="#per-i-facilitatori" aria-label="Permalink to &quot;Per i facilitatori&quot;">​</a></h2><h3 id="lista-di-controllo-per-la-preparazione" tabindex="-1">Lista di controllo per la preparazione <a class="header-anchor" href="#lista-di-controllo-per-la-preparazione" aria-label="Permalink to &quot;Lista di controllo per la preparazione&quot;">​</a></h3><p><strong>1 settimana prima:</strong></p><ul><li>[ ] Prenota la stanza per 2-3 ore</li><li>[ ] Invita 6-12 partecipanti</li><li>[ ] Aggiungi ai preferiti le pagine dei materiali (vedi <a href="/it/mental-journey/materials">Materiali</a>)</li><li>[ ] Leggi attentamente questa guida</li><li>[ ] Preparare una lavagna a fogli mobili o una lavagna bianca</li></ul><p><strong>1 giorno prima:</strong></p><ul><li>[ ] Conferma la presenza</li><li>[ ] Allestimento della sala (posti a sedere in cerchio)</li><li>[ ] Prova qualsiasi tecnologia (diapositive, ecc.)</li><li>[ ] Preparare i materiali</li></ul><p><strong>1 ora prima:</strong></p><ul><li>[ ] Arrivare presto</li><li>[ ] Disporre i posti a sedere in cerchio</li><li>[ ] Materiali di installazione</li><li>[ ] Concentrati</li></ul><h3 id="il-tuo-ruolo-di-facilitatore" tabindex="-1">Il tuo ruolo di facilitatore <a class="header-anchor" href="#il-tuo-ruolo-di-facilitatore" aria-label="Permalink to &quot;Il tuo ruolo di facilitatore&quot;">​</a></h3><div class="warning custom-block"><p class="custom-block-title">Importante</p><p><strong>Non</strong> sei un terapeuta o un coach tecnico. Sei un <strong>facilitatore</strong> che:</p><ul><li>Discussione sulle guide</li><li>Crea uno spazio sicuro</li><li>Collega i concetti all&#39;esperienza</li><li>Gestisce le dinamiche di gruppo</li></ul></div><p><strong>Competenze chiave:</strong></p><ul><li>Ascolto attivo</li><li>Presenza neutrale</li><li>Gestire diverse personalità</li><li>Sapere quando andare avanti</li></ul><h3 id="piano-dettagliato-della-sessione" tabindex="-1">Piano dettagliato della sessione <a class="header-anchor" href="#piano-dettagliato-della-sessione" aria-label="Permalink to &quot;Piano dettagliato della sessione&quot;">​</a></h3><hr><h4 id="parte-1-introduzione-20-minuti" tabindex="-1">Parte 1: Introduzione (20 minuti) <a class="header-anchor" href="#parte-1-introduzione-20-minuti" aria-label="Permalink to &quot;Parte 1: Introduzione (20 minuti)&quot;">​</a></h4><p><strong>Obiettivi:</strong></p><ul><li>Creare sicurezza psicologica</li><li>Definisci le aspettative</li><li>Costruisci una connessione di gruppo</li></ul><p><strong>Sceneggiatura:</strong></p><p>&quot;Benvenuti a tutti. Questa sessione riguarda il gioco mentale della pétanque: i pensieri, le emozioni e gli schemi che influenzano la vostra prestazione.</p><p><strong>Regole di base:</strong></p><ol><li>Ciò che viene condiviso qui rimane qui</li><li>Nessun giudizio sulle esperienze degli altri</li><li>La partecipazione è volontaria</li><li>Non ci sono risposte sbagliate</li></ol><p><strong>Gioco veloce:</strong> Nome, da quanto tempo giochi, una sfida mentale che affronti.</p><p><strong>Note del facilitatore:</strong></p><ul><li>Vai prima alla vulnerabilità del modello</li><li>Mantieni le presentazioni brevi (1 minuto ciascuna)</li><li>Nota temi comuni</li><li>Convalida tutte le risposte</li></ul><hr><h4 id="parte-2-lo-stato-di-zona-flusso-40-minuti" tabindex="-1">Parte 2: Lo stato di zona/flusso (40 minuti) <a class="header-anchor" href="#parte-2-lo-stato-di-zona-flusso-40-minuti" aria-label="Permalink to &quot;Parte 2: Lo stato di zona/flusso (40 minuti)&quot;">​</a></h4><p><strong>Obiettivi:</strong></p><ul><li>Comprendere gli stati di flusso</li><li>Riconoscere la modalità tecnica rispetto a quella di flusso</li><li>Impara il concetto di &quot;switch&quot;</li></ul><p><strong>Domanda di apertura:</strong> &quot;Pensa a una volta in cui hai giocato la tua migliore partita a bocce. Che sensazioni hai provato? Cosa è stato diverso?&quot;</p><p><strong>Spunti di discussione:</strong></p><ol><li>&quot;Quanti di voi hanno giocato partite in cui tutto è andato per il verso giusto?&quot;</li><li>&quot;A cosa pensavi in quei momenti?&quot;</li><li>&quot;In che cosa è diverso da quando sei in difficoltà?&quot;</li></ol><p><strong>Punti chiave dell&#39;insegnamento:</strong></p><p>Utilizzare la lavagna per disegnare:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>PLANNING MODE          →    EXECUTION MODE</span></span>\n<span class="line"><span>(Outside circle)            (Inside circle)</span></span>\n<span class="line"><span>- Analyze situation         - Eyes on target</span></span>\n<span class="line"><span>- Choose strategy           - Trust training</span></span>\n<span class="line"><span>- Decide throw type         - Automatic movement</span></span></code></pre></div><p><strong>Esercizio: The Switch (10 minuti)</strong></p><p>&quot;Pratichiamo il momento di commutazione:</p><ol><li>In piedi</li><li>Immagina di essere fuori dal cerchio: pensa a uno scatto</li><li>Fai un respiro</li><li>Fai un passo avanti (nel cerchio immaginario)</li><li>Mentre fai un passo, lascia andare l&#39;analisi</li><li>Concentrati solo su un bersaglio immaginario&quot;</li></ol><p><strong>Debriefing:</strong></p><ul><li>&quot;Cosa hai notato?&quot;</li><li>&quot;È stato facile o difficile smettere di pensare?&quot;</li><li>&quot;Come potrebbe applicarsi questo ai giochi reali?&quot;</li></ul><hr><h4 id="parte-3-pausa-10-minuti" tabindex="-1">Parte 3: Pausa (10 minuti) <a class="header-anchor" href="#parte-3-pausa-10-minuti" aria-label="Permalink to &quot;Parte 3: Pausa (10 minuti)&quot;">​</a></h4><p><strong>Azioni del facilitatore:</strong></p><ul><li>Incoraggiare la discussione informale</li><li>Nota l&#39;energia del gruppo</li><li>Preparati per la prossima sezione</li></ul><hr><h4 id="parte-4-il-critico-interiore-40-minuti" tabindex="-1">Parte 4: Il critico interiore (40 minuti) <a class="header-anchor" href="#parte-4-il-critico-interiore-40-minuti" aria-label="Permalink to &quot;Parte 4: Il critico interiore (40 minuti)&quot;">​</a></h4><p><strong>Obiettivi:</strong></p><ul><li>Riconoscere i modelli di dialogo interiore negativo</li><li>Distinguere il critico interiore dal coach interiore</li><li>Praticare l&#39;osservazione neutrale</li></ul><p><strong>Apertura:</strong> &quot;Abbiamo tutti una voce interiore che commenta le nostre prestazioni. A volte è utile, a volte è dura. Esploriamola.&quot;</p><p><strong>Esercizio: Inventario del critico interiore (15 minuti)</strong></p><p>&quot;Sul tuo foglio scrivi:</p><ol><li>Cosa dice la tua voce interiore dopo un brutto lancio</li><li>Cosa dice quando sei sotto pressione</li><li>Cosa dice sulle tue capacità&quot;</li></ol><p><em>Dedica 5 minuti alla scrittura</em></p><p>&quot;Ora, chi è disposto a condividere un esempio?&quot;</p><p><strong>Note del facilitatore:</strong></p><ul><li>Normalizzare i dialoghi interiori duri</li><li>Non cercare di &quot;aggiustare&quot; nessuno</li><li>Cercare modelli comuni</li></ul><p><strong>Insegnamento: Critico Interiore vs Coach Interiore (15 minuti)</strong></p><p>Disegna due colonne sulla lavagna:</p><table tabindex="0"><thead><tr><th>Critico interiore</th><th>Coach interiore</th></tr></thead><tbody><tr><td>&quot;Come hai potuto non accorgertene?!&quot;</td><td>&quot;Quello è andato a sinistra&quot;</td></tr><tr><td>&quot;Ti strozzi sempre&quot;</td><td>&quot;Proviamo di nuovo&quot;</td></tr><tr><td>&quot;Sei terribile&quot;</td><td>&quot;Cosa posso imparare?&quot;</td></tr></tbody></table><p><strong>Discussione:</strong></p><ul><li>&quot;Hai notato la differenza?&quot;</li><li>&quot;Quale voce aiuta la performance?&quot;</li><li>&quot;Puoi cambiare la voce?&quot;</li></ul><p><strong>Esercitazione: Riformulazione (10 minuti)</strong></p><p>&quot;Prendi una delle affermazioni del tuo Critico Interiore. Come la direbbe un Coach Interiore?&quot;</p><p>Condividi esempi.</p><hr><h4 id="parte-5-strumenti-pratici-40-minuti" tabindex="-1">Parte 5: Strumenti pratici (40 minuti) <a class="header-anchor" href="#parte-5-strumenti-pratici-40-minuti" aria-label="Permalink to &quot;Parte 5: Strumenti pratici (40 minuti)&quot;">​</a></h4><p><strong>Obiettivi:</strong></p><ul><li>Impara il reset a 3 respiri</li><li>Crea una semplice routine pre-tiro</li><li>Comprendere il recupero degli errori</li></ul><p><strong>Strumento 1: Reset dei 3 respiri (10 minuti)</strong></p><p>&quot;Questo è il pulsante di ripristino di emergenza. Usalo quando senti che la pressione sta aumentando.&quot;</p><p><strong>Dimostrare:</strong></p><ol><li>Inspira per 4 conteggi</li><li>Mantieni la posizione per 2 conteggi</li><li>Espirare per 6 conteggi</li><li>Ripeti 3 volte</li></ol><p>&quot;Adesso facciamo pratica insieme.&quot;</p><p><em>Guida il gruppo attraverso 3 cicli</em></p><p><strong>Debriefing:</strong></p><ul><li>&quot;Cosa hai notato nel tuo corpo?&quot;</li><li>&quot;Quando potresti usarlo?&quot;</li></ul><p><strong>Strumento 2: Semplice routine pre-tiro (15 minuti)</strong></p><p>&quot;Una routine ti aiuta a passare dalla pianificazione all&#39;esecuzione in modo coerente.&quot;</p><p><strong>Struttura di base:</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Outside Circle (Planning):</span></span>\n<span class="line"><span>- Look at situation</span></span>\n<span class="line"><span>- Decide on throw</span></span>\n<span class="line"><span>- See the result in your mind</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>Walking to Circle (Transition):</span></span>\n<span class="line"><span>- One deep breath</span></span>\n<span class="line"><span>- Let go of analysis</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>Inside Circle (Execution):</span></span>\n<span class="line"><span>- Eyes on target only</span></span>\n<span class="line"><span>- Trust your training</span></span>\n<span class="line"><span>- Execute</span></span></code></pre></div><p><strong>Esercizio:</strong> &quot;Crea la tua routine in 3 fasi. Scrivila.&quot;</p><p>Condividi esempi.</p><p><strong>Strumento 3: Protocollo di recupero degli errori (15 minuti)</strong></p><p>&quot;I giocatori d&#39;élite non commettono meno errori. Recuperano più velocemente.&quot;</p><p><strong>Protocollo in 3 fasi:</strong></p><ol><li><strong>Osserva</strong> - Esponi il fatto in modo neutrale (&quot;Quello è andato a sinistra&quot;)</li><li><strong>Impara</strong> - Estrai informazioni (&quot;Il vento è più forte di quanto pensassi&quot;)</li><li><strong>Reset</strong> - Muoviti in avanti (reset con 3 respiri, occhi in avanti)</li></ol><p><strong>Pratica:</strong> &quot;Pensa a un errore recente. Esegui i 3 passaggi.&quot;</p><hr><h4 id="parte-6-integrazione-e-chiusura-20-minuti" tabindex="-1">Parte 6: Integrazione e chiusura (20 minuti) <a class="header-anchor" href="#parte-6-integrazione-e-chiusura-20-minuti" aria-label="Permalink to &quot;Parte 6: Integrazione e chiusura (20 minuti)&quot;">​</a></h4><p><strong>Obiettivi:</strong></p><ul><li>Consolidare l&#39;apprendimento</li><li>Creare piani d&#39;azione</li><li>Fornire risorse</li></ul><p><strong>Domande di riflessione:</strong></p><ol><li>&quot;Qual è l&#39;intuizione che stai traendo da questa esperienza?&quot;</li><li>&quot;Qual è la cosa che proverai questa settimana?&quot;</li><li>&quot;Quali domande restano?&quot;</li></ol><p><strong>Pianificazione dell&#39;azione (10 minuti)</strong></p><p>&quot;Sul tuo volantino scrivi:</p><ol><li>Una tecnica che metterai in pratica questa settimana</li><li>Quando/dove lo praticherai</li><li>Come monitorerai i tuoi progressi&quot;</li></ol><p><strong>Risorse:</strong></p><ul><li>Distribuire il foglio riassuntivo</li><li>Condividi il sito web: carreau.app</li><li>Modulo di partenza consigliato: <a href="/it/education/the-zone/">The Zone</a></li></ul><p><strong>Cerchio di chiusura:</strong> &quot;Una parola per descrivere come ti senti in questo momento.&quot;</p><p><strong>Parole finali:</strong> &quot;L&#39;allenamento mentale è un&#39;abilità come qualsiasi altra: richiede pratica. Inizia in piccolo, sii paziente con te stesso e nota i cambiamenti. Grazie per la tua disponibilità oggi.&quot;</p><hr><h3 id="suggerimenti-per-il-facilitatore" tabindex="-1">Suggerimenti per il facilitatore <a class="header-anchor" href="#suggerimenti-per-il-facilitatore" aria-label="Permalink to &quot;Suggerimenti per il facilitatore&quot;">​</a></h3><h4 id="gestire-situazioni-difficili" tabindex="-1">Gestire situazioni difficili <a class="header-anchor" href="#gestire-situazioni-difficili" aria-label="Permalink to &quot;Gestire situazioni difficili&quot;">​</a></h4><p><strong>Se qualcuno domina:</strong></p><ul><li>&quot;Grazie [nome]. Sentiamo cosa ne pensano gli altri.&quot;</li><li>Utilizzare turni strutturati</li></ul><p><strong>Se qualcuno oppone resistenza:</strong></p><ul><li>Non discutere</li><li>&quot;È una prospettiva valida. Cosa ne pensano gli altri?&quot;</li><li>Allinearsi con le loro preoccupazioni</li></ul><p><strong>Se qualcuno si emoziona:</strong></p><ul><li>Normalizzalo</li><li>&quot;Questo tocca qualcosa di reale. Grazie per averlo condiviso.&quot;</li><li>Non cercare di risolvere</li></ul><p><strong>Se la discussione si blocca:</strong></p><ul><li>Utilizzare prompt specifici</li><li>Condividi il tuo esempio</li><li>Passare a un esercizio</li></ul><h4 id="gestione-dell-39-energia" tabindex="-1">Gestione dell&#39;energia <a class="header-anchor" href="#gestione-dell-39-energia" aria-label="Permalink to &quot;Gestione dell&amp;#39;energia&quot;">​</a></h4><p><strong>Alta energia:</strong> Usa esercizi e movimento <strong>Bassa energia:</strong> Fai domande provocatorie <strong>Sparsi:</strong> Riportare alla struttura <strong>Tempo:</strong> Usa l&#39;umorismo o la pausa</p><h3 id="post-sessione" tabindex="-1">Post-sessione <a class="header-anchor" href="#post-sessione" aria-label="Permalink to &quot;Post-sessione&quot;">​</a></h3><p><strong>Seguito:</strong></p><ul><li>Invia un&#39;e-mail di riepilogo entro 24 ore</li><li>Includi link alle risorse</li><li>Offriti di rispondere alle domande</li><li>Pianifica una sessione di follow-up facoltativa</li></ul><p><strong>Autoriflessione:</strong></p><ul><li>Cosa ha funzionato bene?</li><li>Cosa cambieresti?</li><li>Cosa ti ha sorpreso?</li><li>Cosa hai imparato?</li></ul><hr><h2 id="materiali" tabindex="-1">Materiali <a class="header-anchor" href="#materiali" aria-label="Permalink to &quot;Materiali&quot;">​</a></h2><ul><li><a href="/it/mental-journey/materials#participant-guide">Guida per i partecipanti</a></li><li><a href="/it/mental-journey/materials#facilitator-slides">Diapositive per il facilitatore</a></li><li><a href="/it/mental-journey/materials#summary-sheet">Scheda riassuntiva</a></li><li><a href="/it/mental-journey/materials#exercise-worksheets">Schede di esercizi</a></li></ul><hr><div class="tip custom-block"><p class="custom-block-title">Pronti a facilitare?</p><ol><li>Leggi attentamente questa guida</li><li>Scarica i materiali</li><li>Esercitati tu stesso negli esercizi</li><li>Pianifica la tua sessione</li><li>Fidati del processo</li></ol></div>',140))])}]]);export{p as __pageData,c as default};
